  async function runSetupPreflight() {
    if (!state.setup.mutationToken) return;
    const preflight = state.setup.preflight;
    preflight.busy = true;
    preflight.error = "";
    renderSetupDatabaseStage();
    try {
      const data = await api("/api/calliope/setup/preflight", setupMutationOptions());
      preflight.snapshot = data.preflight;
      toast(data.preflight?.ready ? "Managed services passed active checks" : "Managed services need operator attention", !data.preflight?.ready);
      await refreshSetupReceipts();
      if (data.preflight?.ready) {
        await continueSetupAfter(
          "preflight",
          "The managed appliance self-check passed automatically. Welcome me briefly, explain that the infrastructure is ready, and guide me through the company context next. Use the Stage for the company fields and do not ask me to navigate the checklist.",
        );
      } else {
        guideSetupOnce(
          "preflight-needs-attention",
          "The automatic managed-appliance self-check found items that need attention. Explain the credential-free failures in plain language and repair any local Calliope or RVBBIT configuration you can before asking me for anything.",
        );
      }
    } catch (error) {
      preflight.error = error.message;
    } finally {
      preflight.busy = false;
      renderSetupDatabaseStage();
    }
  }

